contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;
        uint beforeTestBalance = address(this).balance;

        c.Put{value: 0}(lockTime); if (__ESBMC_reverted()) return;

        (uint afterUnlock, uint afterBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;

        assert(afterBal == beforeBal && afterUnlock == beforeUnlock && afterContractBalance == beforeContractBalance && address(this).balance == beforeTestBalance);
    }

    receive() external payable {}
}

